package main

import (
	"context"
	"fmt"
	"time"
)

// worker 函数模拟一个并发任务，监听 Context 的取消信号
func worker(ctx context.Context, id int) {
	for {
		select {
		case <-ctx.Done():
			fmt.Printf("Worker %d: stopped, reason: %v\n", id, ctx.Err())
			return
		default:
			// 模拟工作负载
			fmt.Printf("Worker %d: working\n", id)
			time.Sleep(100 * time.Millisecond)
		}
	}
}

func main() {
	// 创建一个可取消的根 Context
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel() // 确保在 main 结束时调用 cancel

	// 启动多个 worker goroutine，共享同一个 Context
	for i := 0; i < 3; i++ {
		go worker(ctx, i)
	}

	// 模拟主函数工作一段时间后取消 Context
	time.Sleep(500 * time.Millisecond)
	fmt.Println("Main: canceling context")
	cancel() // 取消 Context，所有 worker 将停止

	// 等待一段时间以观察 goroutine 停止
	time.Sleep(200 * time.Millisecond)
	fmt.Println("Main: all workers should have stopped")
}

