package main

import (
	"context"
	"fmt"
	"time"
)

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()

	select {
	case <-ctx.Done():
		fmt.Println("Context done:", ctx.Err())
	case <-time.After(200 * time.Millisecond):
		fmt.Println("Time after")
	}
}
